// Des: Turn plain words into a job and its arguments (non-tech mode)
// Flo: lowercase the words > match a phrase prefix > put the rest in the right slot > preset params for "get <url> as text|html|json|markdown"
// I/O: words (caller) > job name + Args, or null when not understood
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const fld = @import("ut-text-fold.zig");
pub const Slot = enum { none, url, text, title, to, opt };
pub const Rule = struct { pref: []const u8, job: []const u8, slot: Slot };
pub const RULES = [_]Rule{ .{ .pref = "get ", .job = "fetch-run", .slot = .url }, .{ .pref = "scrape ", .job = "fetch-run", .slot = .url }, .{ .pref = "sign up", .job = "signup", .slot = .none }, .{ .pref = "log in", .job = "login", .slot = .none }, .{ .pref = "login", .job = "login", .slot = .none }, .{ .pref = "log out", .job = "logout", .slot = .none }, .{ .pref = "verify ", .job = "verify-email", .slot = .text }, .{ .pref = "code ", .job = "verify-email", .slot = .text }, .{ .pref = "show usage", .job = "usage-view", .slot = .none }, .{ .pref = "show plan", .job = "plan-view", .slot = .none }, .{ .pref = "show invoices", .job = "invoice-list", .slot = .none }, .{ .pref = "show logs", .job = "logs-view", .slot = .none }, .{ .pref = "show analytics", .job = "analytics-view", .slot = .none }, .{ .pref = "create key ", .job = "key-create", .slot = .title }, .{ .pref = "delete key", .job = "key-revoke", .slot = .none }, .{ .pref = "add webhook ", .job = "webhook-add", .slot = .url }, .{ .pref = "invite ", .job = "team-invite", .slot = .to }, .{ .pref = "upgrade to ", .job = "plan-change", .slot = .opt }, .{ .pref = "cancel subscription", .job = "sub-cancel", .slot = .none }, .{ .pref = "docs ", .job = "docs-search", .slot = .text }, .{ .pref = "help me ", .job = "support-send", .slot = .text }, .{ .pref = "turn 2fa on", .job = "twofa-on", .slot = .none }, .{ .pref = "turn 2fa off", .job = "twofa-off", .slot = .none } };
pub const Cmd = struct { job: []const u8, args: task.Args };
fn fmtOpt(tail: []const u8) []const u8 { if (std.ascii.eqlIgnoreCase(tail, "text")) return "response_type=plaintext"; if (std.ascii.eqlIgnoreCase(tail, "markdown")) return "response_type=markdown"; if (std.ascii.eqlIgnoreCase(tail, "json")) return "json_response=true"; return ""; }
pub fn parse(aren: std.mem.Allocator, text: []const u8) !?Cmd { const trimmed = std.mem.trim(u8, text, " \t\r\n"); const low = try fld.foldAlloc(aren, trimmed); for (RULES) |rul| { if (!std.mem.startsWith(u8, low, rul.pref)) continue; const rest = std.mem.trim(u8, trimmed[rul.pref.len..], " "); var cmd: Cmd = .{ .job = rul.job, .args = .{} }; switch (rul.slot) { .none => {}, .url => { const at = std.mem.find(u8, rest, " as "); cmd.args.url = if (at) |ix| std.mem.trim(u8, rest[0..ix], " ") else rest; if (at) |ix| cmd.args.opt = fmtOpt(std.mem.trim(u8, rest[ix + 4 ..], " ")); }, .text => cmd.args.text = rest, .title => cmd.args.title = rest, .to => cmd.args.to = rest, .opt => cmd.args.opt = rest } return cmd; } return null; }
